<style>
.inventory-ops-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:1rem;align-items:start}.inventory-ops-stack{display:grid;gap:1rem}.inventory-ops-metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.inventory-ops-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.85rem}.inventory-ops-card{border:1px solid var(--border);border-radius:16px;padding:1rem;background:var(--surface);display:grid;gap:.7rem}.inventory-ops-card header{display:flex;justify-content:space-between;gap:.8rem;align-items:flex-start}.inventory-ops-card h3{margin:0;font-size:1rem}.inventory-ops-card p{margin:0;color:var(--muted);font-size:.9rem}.inventory-ops-kv{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.55rem}.inventory-ops-kv div{padding:.65rem;border-radius:12px;background:var(--surface-soft)}.inventory-ops-kv span{display:block;color:var(--muted);font-size:.75rem}.inventory-ops-kv strong{display:block;margin-top:.2rem}.inventory-ops-actions{display:flex;flex-wrap:wrap;gap:.45rem;align-items:center}.inventory-ops-actions form{display:inline-flex}.inventory-ops-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.inventory-ops-form .span-2{grid-column:1/-1}.inventory-ops-form label>span{display:block;font-size:.78rem;font-weight:700;margin-bottom:.3rem}.inventory-ops-form textarea{min-height:88px}.inventory-ops-timeline{display:grid;gap:.65rem}.inventory-ops-event{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:.75rem;padding:.75rem;border:1px solid var(--border);border-radius:13px;align-items:start}.inventory-ops-event time{font-size:.78rem;color:var(--muted)}.inventory-ops-event p{margin:.2rem 0 0;color:var(--muted);font-size:.85rem}.inventory-ops-progress{height:8px;background:var(--surface-soft);border-radius:999px;overflow:hidden}.inventory-ops-progress i{display:block;height:100%;background:currentColor;border-radius:999px}.inventory-ops-callout{padding:.85rem;border:1px solid var(--border);border-radius:14px;background:var(--surface-soft)}.inventory-ops-callout strong{display:block}.inventory-ops-callout p{margin:.25rem 0 0;color:var(--muted)}
@media(max-width:1100px){.inventory-ops-grid{grid-template-columns:1fr}.inventory-ops-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.inventory-ops-card-grid,.inventory-ops-form,.inventory-ops-kv,.inventory-ops-metrics{grid-template-columns:1fr}.inventory-ops-event{grid-template-columns:1fr}.inventory-ops-form .span-2{grid-column:auto}}
</style>
